 function circleBezier(curve,t){const n=curve.degree,[lo,hi]=curve.parameter_range??[curve.knots[n],curve.knots[curve.knots.length-n-1]],x=(t-lo)/(hi-lo);let binomial=1,weight=0;const p=[0,0,0];for(let i=0;i<=n;i++){if(i)binomial*=((n-i+1)/i);const b=binomial*x**i*(1-x)**(n-i)*curve.weights[i];weight+=b;for(let j=0;j<3;j++)p[j]+=b*curve.control_points[i][j];}return p.map(v=>v/weight);}
 function checkRoofCircle(data){const path=data.rational_roof_path;assert.equal(path.closed,true);assert.equal(path.stock_unchanged,true);assert.equal(path.bore_created,false);assert.equal(path.quarters.length,4);assert.equal(data.brep.closed,true);assert.equal(data.brep.faces,6);assert.equal(data.brep.edges,12);const a=data.placement.angle,c=Math.cos(a),s=Math.sin(a),tr=data.placement.translation,local=p=>{const x=p[0]-tr[0],y=p[1]-tr[1],z=p[2]-tr[2];return[c*x-s*z,y,s*x+c*z];};for(let qi=0;qi<4;qi++){const q=path.quarters[qi];assert.equal(q.curve.degree,8);assert.equal(q.pcurve.degree,2);assert.ok(q.curve.weights.every(w=>w>0&&Number.isFinite(w)));assert.ok(Math.max(...q.curve.weights)-Math.min(...q.curve.weights)>.01);assert.deepEqual(q.points.at(-1),path.quarters[(qi+1)%4].points[0]);assert.equal(q.error_bounds.length,q.points.length-1);assert.equal(q.parameters.length,q.points.length);assert.ok(q.error_bounds.every(e=>e>=0&&e<=data.error));for(let j=0;j<=64;j++){const t=q.curve.parameter_range[0]+(q.curve.parameter_range[1]-q.curve.parameter_range[0])*j/64,p=circleBezier(q.curve,t),uv=circleBezier(q.pcurve,t),xyz=local(p),z=data.height+4*data.bulge*uv[0]*(1-uv[0])*uv[1]*(1-uv[1]);assert.ok(Math.abs(xyz[0]-data.width*uv[0])<1e-8);assert.ok(Math.abs(xyz[1]-data.depth*uv[1])<1e-8);assert.ok(Math.abs(xyz[2]-z)<1e-8);assert.ok(Math.abs(Math.hypot(xyz[0]-path.center[0],xyz[1]-path.center[1])-path.radius)<1e-8);}for(let j=0;j<q.error_bounds.length;j++)for(const f of[.25,.5,.75]){const t=q.parameters[j]+f*(q.parameters[j+1]-q.parameters[j]),p=circleBezier(q.curve,t),chord=q.points[j].map((x,i)=>x+f*(q.points[j+1][i]-x));assert.ok(Math.hypot(...p.map((x,i)=>x-chord[i]))<=q.error_bounds[j]+1e-8);}}const F=(a,b)=>(b*b-a*a)/2-(b*b*b-a*a*a)/3,[u,v]=data.source_domain,expected=data.width*data.depth*(data.height*(u[1]-u[0])*(v[1]-v[0])+4*data.bulge*F(...u)*F(...v));assert.ok(Math.abs(data.volume-expected)<1e-8);}
