 function filletCurve(curve,t){return curve.kind==='line'?curve.a.map((x,i)=>x+(curve.b[i]-x)*t):curve.frame.origin.map((x,i)=>x+curve.radius*(Math.cos(t)*curve.frame.axes[0][i]+Math.sin(t)*curve.frame.axes[1][i]));}
