 function boundedNumericParity(actual,expected,path='bounded import'){if(typeof actual==='number'&&typeof expected==='number'){if(Number.isInteger(actual)&&Number.isInteger(expected))assert.equal(actual,expected,path);else assert.ok(Number.isFinite(actual)&&Number.isFinite(expected)&&Math.abs(actual-expected)<=32*Number.EPSILON*Math.max(1,Math.abs(actual),Math.abs(expected)),`${path}: ${actual} vs ${expected}`);return;}if(path.endsWith('.step')){const tokens=text=>text.match(/'(?:[^']|'')*'|#\d+|[+-]?(?:\d+\.?\d*|\.\d+)(?:[Ee][+-]?\d+)?|[^\d'#]+|./g),a=tokens(actual),b=tokens(expected);assert.equal(a.length,b.length,path+' token count');for(let i=0;i<a.length;i++){if(/^[+-]?(?:\d+\.?\d*|\.\d+)(?:[Ee][+-]?\d+)?$/.test(a[i])&&/^[+-]?(?:\d+\.?\d*|\.\d+)(?:[Ee][+-]?\d+)?$/.test(b[i])){const x=Number(a[i]),y=Number(b[i]);assert.ok(Number.isFinite(x)&&Number.isFinite(y),path+' finite numeric token '+i);if(Number.isInteger(x)&&Number.isInteger(y))assert.equal(x,y,path+' integer token '+i);else assert.ok(Math.abs(x-y)<=32*Number.EPSILON*Math.max(1,Math.abs(x),Math.abs(y)),path+' numeric token '+i);}else assert.equal(a[i],b[i],path+' token '+i);}return;}if(actual&&expected&&typeof actual==='object'&&typeof expected==='object'){assert.equal(Array.isArray(actual),Array.isArray(expected),path);assert.deepEqual(Object.keys(actual).sort(),Object.keys(expected).sort(),path+' keys');for(const key of Object.keys(actual))boundedNumericParity(actual[key],expected[key],path+'.'+key);return;}assert.equal(actual,expected,path);}
