 function checkArcSplit(data,offset=0,angle=0,translation=[0,0,0]){const source=20*(4800-(4-Math.PI)*64);assert.ok(Math.abs(data.source.volume-source)<1e-6);assert.ok(Math.abs(data.negative.volume+data.positive.volume-source)<1e-6);if(offset===0)assert.ok(Math.abs(data.negative.volume-source/2)<1e-6);if(offset===34){const a=2,r=8,cap=r*r*Math.acos(a/r)-a*Math.sqrt(r*r-a*a);assert.ok(Math.abs(data.positive.volume-20*(44*6+cap))<1e-6,'Independent circular-segment volume');}for(const side of['negative','positive']){const body=data[side];assert.equal(body.brep.closed,true);const uses=Array.from({length:body.brep.edges},()=>[]);body.brep.wires.forEach((wires,fi)=>wires.forEach(wire=>wire.forEach(c=>{uses[c.edge].push(c.forward);const curve=body.brep.curves[c.edge];for(let j=0;j<=32;j++){const t=curve.parameter_range[0]+(curve.parameter_range[1]-curve.parameter_range[0])*j/32,p=filletCurve(curve,t),pc=c.pcurve,uv=pc.kind==='affine'?pc.origin.map((x,i)=>x+t*pc.direction[i]):pc.center.map((x,i)=>x+pc.radius*(i===0?Math.cos(pc.start_angle+t):Math.sin(pc.start_angle+t))),q=filletSurface(body.brep.surfaces[fi],uv);assert.ok(Math.hypot(...p.map((x,i)=>x-q[i]))<=data.linear_tolerance);}})));for(const u of uses){assert.equal(u.length,2);assert.notEqual(u[0],u[1]);}assert.ok(body.error_bounds.every(e=>Number.isFinite(e)&&e>=0&&e<=data.display_chord_tolerance));const meshUses=new Map();for(const tri of body.mesh.triangles){const ids=tri.map(id=>body.mesh.positions[id].map(x=>Math.round(x/1e-8)).join(','));for(let j=0;j<3;j++){const a=ids[j],b=ids[(j+1)%3],key=a<b?a+'|'+b:b+'|'+a,u=meshUses.get(key)||[0,0];u[0]++;u[1]+=a<b?1:-1;meshUses.set(key,u);}}for(const u of meshUses.values()){assert.equal(u[0],2);assert.equal(u[1],0);}for(const p of body.mesh.positions){const q=p.map((x,i)=>x-translation[i]),x=Math.cos(angle)*q[0]-Math.sin(angle)*q[2];assert.ok(side==='negative'?x<=offset+1e-6:x>=offset-1e-6,'Actual selected half-space');}}}
