 function checkArcLineBore(data,radius=8,angle=0,translation=[0,0,0]){const expectedSource=20*(4800-(4-Math.PI)*64),expectedRemoved=20*Math.PI*radius**2;assert.ok(Math.abs(data.source.volume-expectedSource)<1e-6);assert.ok(Math.abs(data.removed.volume-expectedRemoved)<1e-6);assert.ok(Math.abs(data.kept.volume-(expectedSource-expectedRemoved))<1e-6);for(const[name,faces,edges,vertices]of[['source',10,24,16],['kept',14,36,24],['removed',6,12,8]]){const part=data[name];assert.equal(part.brep.closed,true);assert.equal(part.brep.faces,faces);assert.equal(part.brep.edges,edges);assert.equal(part.brep.vertices.length,vertices);const uses=Array.from({length:edges},()=>[]);part.brep.wires.forEach((wires,fi)=>wires.forEach(wire=>wire.forEach(c=>{uses[c.edge].push(c.forward);const curve=part.brep.curves[c.edge];for(let j=0;j<=32;j++){const t=curve.parameter_range[1]*j/32,p=filletCurve(curve,t),pc=c.pcurve,uv=pc.kind==='affine'?pc.origin.map((x,i)=>x+t*pc.direction[i]):pc.center.map((x,i)=>x+pc.radius*(i===0?Math.cos(pc.start_angle+t):Math.sin(pc.start_angle+t))),q=filletSurface(part.brep.surfaces[fi],uv);assert.ok(Math.hypot(...p.map((x,i)=>x-q[i]))<=data.linear_tolerance);}})));for(const use of uses){assert.equal(use.length,2);assert.notEqual(use[0],use[1]);}assert.equal(part.error_bounds.length,part.mesh.triangles.length);assert.ok(part.error_bounds.every(x=>Number.isFinite(x)&&x>=0&&x<=data.display_chord_tolerance));const meshUses=new Map(),key=p=>p.map(x=>Math.round(x/1e-8)).join(',');for(let ti=0;ti<part.mesh.triangles.length;ti++){const triangle=part.mesh.triangles[ti].map(id=>part.mesh.positions[id]),ids=triangle.map(key);for(let i=0;i<3;i++){const a=ids[i],b=ids[(i+1)%3],edge=a<b?a+'|'+b:b+'|'+a,sign=a<b?1:-1;assert.notEqual(a,b);const use=meshUses.get(edge)||[0,0];use[0]++;use[1]+=sign;meshUses.set(edge,use);}const surface=part.brep.surfaces[part.mesh.face_ids[ti]];if(surface.kind==='framed_cylinder'){for(const weights of[[1/3,1/3,1/3],[.5,.5,0],[.5,0,.5],[0,.5,.5]]){const p=[0,1,2].map(i=>triangle.reduce((sum,q,j)=>sum+weights[j]*q[i],0)),delta=p.map((x,i)=>x-surface.frame.origin[i]),x=delta.reduce((sum,v,i)=>sum+v*surface.frame.axes[0][i],0),y=delta.reduce((sum,v,i)=>sum+v*surface.frame.axes[1][i],0);assert.ok(Math.abs(Math.hypot(x,y)-surface.radius)<=part.error_bounds[ti]+1e-8,'Actual cylinder chord bound');}}}for(const use of meshUses.values()){assert.equal(use[0],2,'Closed welded bore display');assert.equal(use[1],0,'Opposing welded display orientations');}}assert.equal(data.kept.brep.wires.filter(w=>w.length===2).length,2);const local=p=>{const q=p.map((x,i)=>x-translation[i]);return[Math.cos(angle)*q[0]-Math.sin(angle)*q[2],q[1],Math.sin(angle)*q[0]+Math.cos(angle)*q[2]];};for(let ti=0;ti<data.kept.mesh.triangles.length;ti++){const surface=data.kept.brep.surfaces[data.kept.mesh.face_ids[ti]];if(surface.kind==='framed_cylinder'&&Math.hypot(...local(surface.frame.origin).slice(0,2))<1e-8){const id=data.kept.mesh.triangles[ti][0],p=local(data.kept.mesh.positions[id]),normal=data.kept.mesh.normals[id],n=[Math.cos(angle)*normal[0]-Math.sin(angle)*normal[2],normal[1]];assert.ok(n[0]*p[0]+n[1]*p[1]<0,'Retained bore cylinder normals point into opening');}const triangle=data.kept.mesh.triangles[ti].map(id=>local(data.kept.mesh.positions[id]));if(triangle.every(p=>Math.abs(p[2])<1e-8)||triangle.every(p=>Math.abs(p[2]-20)<1e-8)){const p=[0,1].map(i=>triangle.reduce((sum,q)=>sum+q[i]/3,0));assert.ok(Math.hypot(...p)>=radius-data.display_chord_tolerance-1e-8,'Through opening cap exclusion with chord allowance');}}}
